#!/usr/bin/env node
import { readFile } from 'node:fs/promises';
const [schemaPath, resultPath] = process.argv.slice(2);
if (!schemaPath || !resultPath) process.exit(2);
const [schema, result] = await Promise.all([schemaPath, resultPath].map(async (file) => JSON.parse(await readFile(file, 'utf8'))));
const matches = (value, rule) => {
  if (rule.enum && !rule.enum.includes(value)) return false;
  if (rule.type === 'string' && (typeof value !== 'string' || value.length < (rule.minLength ?? 0))) return false;
  if (rule.type === 'array' && (!Array.isArray(value) || value.some((item) => !matches(item, rule.items)))) return false;
  return true;
};
for (const key of schema.required) if (!(key in result)) process.exit(1);
for (const [key, value] of Object.entries(result)) {
  const rule = schema.properties[key];
  if (!rule || !matches(value, rule)) process.exit(1);
}
